/****************************************************************************
	fcoo-colors.js,

	(c) 2021, FCOO

	https://github.com/FCOO/fcoo-colors
	https://github.com/FCOO

    Constants and methods to name, get and modify different colors used by FCOO Web Applications

****************************************************************************/

(function ($, window/*, document, undefined*/) {
	"use strict";

	//Create fcoo-namespace
    var ns = window.fcoo = window.fcoo || {},
        nsColor = ns.color = ns.color || {};

    //nsColor.colorNames = {id}{da:STRING, en:STRING}
    nsColor.colorNames = {
        blue    : {da: 'blå',    en: 'blue'     },
        purple  : {da: 'lilla',  en: 'purple'   },
        red     : {da: 'rød',    en: 'red'      },
        orange  : {da: 'orange', en: 'orange'   },
        cyan    : {da: 'cyan',   en: 'cyan'     },
        yellow  : {da: 'Gul',    en: 'yellow'   },
        pink    : {da: 'pink',   en: 'pink'     },
        green   : {da: 'grøn',   en: 'green'    },
        gray    : {da: 'grå',    en: 'gray'     }
        };

    var colorName2Index = ['blue', 'purple', 'red', 'orange', 'cyan', 'yellow', 'pink', 'green', 'gray'];
    nsColor.defaultGradient = 4;
    nsColor.defaultOrder    = ["blue", "red", "green", "yellow", "gray", "purple", "pink", "cyan", "orange"];

    //nsColor.colorList  = []{id, name: {da:STRING, en:STRING}} ordred by nsColor.defaultOrder
    nsColor.colorList  = [];

    $.each(nsColor.defaultOrder, function(index, colorId){
        nsColor.colorList.push({
            id  : colorId,
            name: nsColor.colorNames[colorId]
        });
    });


    //The color scheme is from LinkedIn and shown in linkedin-palette-screen.pdf
    //nsColor.colorArray = The colors defined in linkedin-palette-screen.pdf = [gradiant][color]. Eg. colorArray[3, 4] = gradiant 3 of orange
    nsColor.colorArray = [
        //0:Blue    1:Purple    2:Red      3:Orange   4:Cyan     5:Yellow   6:Pink     7:Green    8:Gray
        ['#CFEDFB', '#EBE4FF', '#FFE0DA', '#FFE7BB', '#D2ECEB', '#FFF2B6', '#FFDFF2', '#E0F4BE', '#E6E9EC'],
        ['#9BDAF3', '#D8CCF4', '#FAC2BB', '#F8CD94', '#9EDDDD', '#FBE491', '#FFC4E4', '#C7E59A', '#D0D3D6'],
        ['#68C7EC', '#BFABE6', '#F59890', '#F7B26A', '#69CDCF', '#F7D56B', '#F99ACA', '#AED677', '#B6B9BC'],
        ['#34B3E4', '#A589D9', '#F16D64', '#F59640', '#35BEC1', '#F3C746', '#F371AF', '#95C753', '#A0A3A6'],
        ['#00A0DC', '#8C68CB', '#EC4339', '#F47B16', '#00AEB3', '#EFB920', '#ED4795', '#7CB82F', '#86898C'],
        ['#008CC9', '#7C5BBB', '#DD2E1F', '#EC640C', '#009EA5', '#E6A700', '#E2247F', '#60AA14', '#737679'],
        ['#0077B5', '#6A4BA7', '#C11F1D', '#CD5308', '#008891', '#CA9400', '#C9186E', '#4E8F13', '#595C5F'],
        ['#005E93', '#573B93', '#A40F1C', '#AF4104', '#00727D', '#AA7D00', '#B10C5C', '#3B7511', '#434649'],
        ['#004471', '#452B7F', '#88001A', '#903000', '#005C69', '#8B6700', '#870044', '#295A10', '#303336']
    ];


    //Methods to get the value of different color-names and gradiants.
    nsColor.getColor = function(color, gradient, fromSortedList){
        var colorIndex = typeof color == 'string' ? colorName2Index.indexOf(color) : color;
        return nsColor.getColorList(fromSortedList, gradient)[colorIndex];
    };


    nsColor.getColorRGB =  function(/*color, gradient, fromSortedList*/){
        return window.hexRgb( nsColor.getColor.apply(null, arguments) );
    };

    nsColor.getColorRGBArray =  function(/*color, gradient, fromSortedList*/){
        return window.hexRgb( nsColor.getColor.apply(null, arguments), {format: 'array'} );
    };


    nsColor.getDeltaColor = function(color, deltaGradient = 0, fromSortedList){
        return nsColor.getColor(color, nsColor.defaultGradient + deltaGradient, fromSortedList);
    };


    nsColor.getDeltaColorRGB = function(/*color, deltaGradient = 0, fromSortedList*/){
        return window.hexRgb( nsColor.getDeltaColor.apply(null, arguments) );
    };

    nsColor.getDeltaColorRGBArray =  function(/*color, deltaGradient = 0, fromSortedList*/){
        return window.hexRgb( nsColor.getDeltaColor.apply(null, arguments), {format: 'array'} );
    };


    nsColor.getColorList = function( sorted, gradient = 'DEFAULT' ){
        gradient = gradient == 'DEFAULT' ? nsColor.defaultGradient : gradient;
        var result = [];
        if (sorted){
            $.each(nsColor.defaultOrder, function(dummy, color){
                result.push( nsColor.getColor( color, gradient ) );
            });
        }
        else
            result = nsColor.colorArray[gradient];
        return result;
    };


    /****************************************************************************
    Using chroma.js (https://github.com/gka/chroma.js)
    Create js-versions of sass functions darken, lighten, tint and shade

    chromaBestContrast( color, contrastColors = ['#000000', '#ffffff'] )
    returns the color from contrastColors with the best contrast
    ****************************************************************************/

    //HSL manipulators - from https://github.com/gka/chroma.js/issues/217
    const lighten = (color, hslPercent) => color.set("hsl.l", color.get("hsl.l") + hslPercent);
    const darken = (color, hslPercent) => lighten(color, -hslPercent);
    const sassLightenDarken = (color, percent, dark) => {
        let  hslPercent = window.numeral(percent).value();
        if (hslPercent === null)
            hslPercent = 1;
        color = window.chroma(color);
        return dark ? darken(color, hslPercent).hex() : lighten(color, hslPercent).hex();
    };

    nsColor.sassLighten = ( color, percent ) => sassLightenDarken( color, percent );
    nsColor.sassDarken  = ( color, percent ) => sassLightenDarken( color, percent, true );

    const mix = (color1, color2, percent) => {
        let ratio = window.numeral(percent).value();
        if (ratio === null)
            ratio = 1;
        return window.chroma.mix(color1, color2, ratio);
    };

    nsColor.sassTintColor  = (color, weight) => mix( color, 'white', weight );
    nsColor.sassShadeColor = (color, weight) => mix( color, 'black', weight );

    //chromaBestContrast( color, contrastColors = ['#000000', '#ffffff']
    nsColor.chromaBestContrast = ( color, contrastColors = ['#000000', '#ffffff']) => {
        contrastColors = $.isArray( contrastColors ) ? contrastColors : [contrastColors];
        let bestContrast = 0, result;
        contrastColors.forEach( (textColor) => {
            const contrast = window.chroma.contrast(color, textColor);
            if (contrast > bestContrast){
                bestContrast = contrast;
                result = textColor;
            }
        });
        return window.chroma(result);
    };

    /****************************************************************************
    setRootVar(id, value)
    getRootVar(id)
    setApplicationBaseColor(baseColor)
    ****************************************************************************/
    const adjustId = (id) => id.slice(0, 2) == '--' ? id : '--'+id;
    const root = document.querySelector(':root');

    ns.setRootVar = (id, value) => {
        root.style.setProperty(adjustId(id), value);
    };

    ns.getRootVar = (id) => {
        return getComputedStyle(root).getPropertyValue( adjustId(id) );
    };

    nsColor.setApplicationBaseColor = (baseColor) => {
        baseColor = window.chroma(baseColor);
        ns.setRootVar('--_fcoo-app-base-color', baseColor.hex() );
        ns.setRootVar('--_fcoo-app-base-text-color', nsColor.chromaBestContrast(baseColor).hex() );
    };


}(jQuery, this, document));
;
/****************************************************************************
	fcoo-data-files.js,

	(c) 2018, FCOO

	https://github.com/FCOO/fcoo-data-files
	https://github.com/FCOO

    fcoo.LOCAL_DATA: {boolean}
    fcoo.dataFilePath:
        function([mainDir:STRING|BOOLEAN], subDir:STRING, fileName:STRING) OR
        function(pathAndFileName:STRING) OR
        function(subAndFileName:{mainDirNa<me:STRING|BOOLEAN, subDirName;STRING, fileName:STRING})

    mainDir = STRING or BOOLEAN. if true => "dynamic", if false => "static"

    if fcoo.LOCAL_DATA == false:
    fcoo.dataFilePath("theSubDir", "fileName.json") returns "https://app.fcoo.dk/static/theSubDir/fileName.json"
    fcoo.dataFilePath(false, "theSubDir", "fileName.json") returns "https://app.fcoo.dk/static/theSubDir/fileName.json"
    fcoo.dataFilePath(true, "theSubDir", "fileName.json") returns "https://app.fcoo.dk/dynamic/theSubDir/fileName.json"

    if fcoo.LOCAL_DATA == false and fcoo.path.relative == true
    fcoo.dataFilePath("theSubDir", "fileName.json") returns "/static/theSubDir/fileName.json"
    fcoo.dataFilePath(false, "theSubDir", "fileName.json") returns "/static/theSubDir/fileName.json"
    fcoo.dataFilePath(true, "theSubDir", "fileName.json") returns "/dynamic/theSubDir/fileName.json"


    if fcoo.LOCAL_DATA == true:
    fcoo.dataFilePath("theSubDir", "fileName.json") returns "/src/data/_fileName.json"

****************************************************************************/

(function ($, window/*, document, undefined*/) {
	"use strict";

	//Create fcoo-namespace
    var ns     = window.fcoo = window.fcoo || {},
        nsPath = ns.path = ns.path || {};

    ns.LOCAL_DATA = false;


    //Set default protocol and host
    nsPath.protocol    = nsPath.protocol || 'https:';
    nsPath.defaultHost = 'app.fcoo.dk';
    nsPath.host        = nsPath.host     || nsPath.defaultHost;
    nsPath.relative    = nsPath.relative || {};    //nsPath.relative = BOOLEAN or {static/dymanic: BOOLEAN}. If true dataFileName return a relative
    nsPath.mainDirHost = nsPath.mainDirHost || {}; //{dynamic/static: STRING} Makes it possible to have different host for the two main-dir

    function getTrueMainDir( mainDir ){
        return mainDir ? (mainDir === true ? 'dynamic' : mainDir) : 'static';
    }

    /*********************************************************
    nsPath.dataFileName()
    *********************************************************/
    nsPath.dataFileName = function(){
        // Detect mode
        var host, mainDir, subDir, relative, fileName;

        if (arguments.length == 3){
            //(mainDir: STRING|BOOLEAN, subDir:STRING, fileName:STRING)
            mainDir  = arguments[0];
            subDir   = arguments[1];
            fileName = arguments[2];
        }
        else
        if (arguments.length == 2){
            //(subDir:STRING, fileName:STRING)
            mainDir  = false,   //=> default 'static'
            subDir   = arguments[0];
            fileName = arguments[1];
        }
        else
        if (arguments.length == 1){
            if (typeof arguments[0] == 'string')
                //(pathAndFileName:STRING)
                return arguments[0];
            else {
                //({mainDir:STRING|BOOLEAN, subDirName:STRING, fileName:STRING})
                mainDir  = arguments[0].mainDir || arguments[0].main || false;
                subDir   = arguments[0].subDir  || arguments[0].sub;
                fileName = arguments[0].fileName;
            }
        }

        if (ns.LOCAL_DATA === true)
            return '/src/data/_' + fileName;

        //Find mainDir, host, and relative
        mainDir  = getTrueMainDir(mainDir);
        host     = typeof nsPath.host == 'string' ? nsPath.host : nsPath.host[mainDir] || nsPath.defaultHost;
        relative = nsPath.relative ? (nsPath.relative === true ? true : !!nsPath.relative[mainDir]) : false;

        return  (relative ? '' : nsPath.protocol + '//') +
                (relative ? '' : host) +
                '/' +
                mainDir  + '/' +
                (subDir ? subDir + '/' : '') +
                fileName;
    };

    //Backward compability
    ns.dataFilePath = nsPath.dataFileName;


    /*********************************************************
    nsPath.staticDataFileName (subDir, fileName)
    nsPath.dynamicDataFileName(subDir, fileName)
    nsPath.assetsDataFileName (subDir, fileName)
    *********************************************************/
    nsPath.staticDataFileName = function(subDir, fileName){
        return this.dataFileName(false, subDir, fileName);
    };

    nsPath.dynamicDataFileName = function(subDir, fileName){
        return this.dataFileName(true, subDir, fileName);
    };

    nsPath.assetsDataFileName = function(subDir, fileName){
        return this.dataFileName('assets', subDir, fileName);
    };


    /*********************************************************
    **********************************************************
    nsPath.setCssVar(varName, mainDir, subDir, fileName)
    Create/update css-variabel varName in :root with url( path to fileName )
    **********************************************************
    *********************************************************/
    var dataFileNameAsCssVar = [];
    nsPath.setDataFileNameAsCssVar = function(varName, mainDir, subDir, fileName){
        mainDir = getTrueMainDir( mainDir );
        var root = document.querySelector(':root');

        root.style.setProperty('--'+varName, 'url(' + nsPath.dataFileName(mainDir, subDir, fileName) +')');

        //If new => Add to dataFileNameAsCssVar
        var found = false;
        dataFileNameAsCssVar.forEach( (dataFile) => {
            if ((dataFile.varName == varName) && (dataFile.mainDir == mainDir) && (dataFile.subDir == subDir) && (dataFile.fileName == fileName))
                found = true;
        });
        if (!found)
            dataFileNameAsCssVar.push({'varName': varName, 'mainDir': mainDir, 'subDir': subDir, 'fileName': fileName});
    };

    /*********************************************************
    nsPath.setStaticDataFileNameAsCssVar (varName, subDir, fileName)
    nsPath.setDynamicDataFileNameAsCssVar(varName, subDir, fileName)
    nsPath.setAssetsDataFileNameAsCssVar (varName, subDir, fileName)
    *********************************************************/
    nsPath.setStaticDataFileNameAsCssVar = function(varName, subDir, fileName){
        return this.setDataFileNameAsCssVar(varName, false, subDir, fileName);
    };

    nsPath.setDynamicDataFileNameAsCssVar = function(varName, subDir, fileName){
        return this.setDataFileNameAsCssVar(varName, true, subDir, fileName);
    };

    nsPath.setAssetsDataFileNameAsCssVar = function(varName, subDir, fileName){
        return this.setDataFileNameAsCssVar(varName, 'assets', subDir, fileName);
    };

    /*********************************************************

    *********************************************************/
    nsPath.getCssVar = function(varName){
        var root      = document.querySelector(':root'),
            rootStyle = getComputedStyle(root);
        return rootStyle.getPropertyValue('--'+varName);
    };


    /*********************************************************
    **********************************************************
    nsPath.setPath(path)
    **********************************************************
    *********************************************************/
    nsPath.setPath = function(path){
        $.extend(true, this, path);

        //Update all css-var
        dataFileNameAsCssVar.forEach( (dataFile) => {
            this.setDataFileNameAsCssVar(dataFile.varName, dataFile.mainDir, dataFile.subDir, dataFile.fileName);
        });
        return this;
    };


}(jQuery, this, document));


;
/****************************************************************************
fcoo-application-loading.js

Create and display loading page
****************************************************************************/
(function ($, window/*, document, undefined*/) {
	"use strict";

    //Create fcoo-namespace
    var ns = window.fcoo = window.fcoo || {};

    //Set modernizr-test 'loading' off
    $('html').modernizrOff('loading');

    var loadingCreated = false;

    ns.createLoading = function( versionText ){
        loadingCreated = true;

        var $body = $('body');

        //Backward compability: Remove <dic class="loading">...</div>
        $body.find('div.loading').remove();

        var $loadingDiv = $('<div/>')
                .addClass('loading')
                .prependTo( $body );

        //Find or create div with branch and version-text (ex. "DEMO 6.2.0")
        if (versionText)
            $('<div/>')
                .addClass('version')
                .text( versionText )
                .appendTo( $loadingDiv );

        //Create div with logo
        $('<div class="logo"></div>').appendTo($loadingDiv);

        //Create div with flashing dots
        $('<div/>')
            .addClass('dots')
            .append('<span>.</span><span>.</span><span>.</span>')
            .appendTo($loadingDiv);

        $('html').modernizrOn('loading');

    };

    //On document.ready: Create loading if html has class loading
    $(function() {
        if ($('html').hasClass('loading') && !loadingCreated)
            ns.createLoading();
    });

    /******************************************************
    workingOn /workingOff
    Show / hide rotating icon when 'working...'
    Delay of 1s to prevent flicing when working in short period
    ******************************************************/
    var workingCreated = false,
        workingTimeoutId;
    ns.workingOn = function(){
        $('html').modernizrOff('working');

        if (!workingCreated){
            $('<div/>')
                .addClass('working show-for-working')
                .append($(
                    '<span class="fa-stack fa-3x">'+
                        '<i class="far fa-circle fa-stack-1x" style="color:gray"></i>' +
                        '<i class="far fa-spinner-third fa-spin fa-stack-1x"></i>' +
                    '</span>')
                )
                .prependTo( $('body') );
            workingCreated = true;
        }

        workingTimeoutId = window.setTimeout(() => { $('html').modernizrOn('working') }, 1000);

    }


    ns.workingOff = function(){
        window.clearTimeout(workingTimeoutId);
        $('html').modernizrOff('working');
    }

}(jQuery, this, document));

;
