        da: {da:'Dansk', en:'Danish'},
        en: {da:'Engelsk', en:'English'},
        fo: {da:'Færøsk', en:'Faroese', fo:'Føroyskt'},
        kl: {da:'Grønlandsk', en:'Greenlandic', kl:'Kalaallisut'},
        de: {da:'Tysk', en:'German', de:'Deutsch'},
