        '2-3'  : { maps: 5,  className: 'multi-map-3-2 multi-map-reverse',   mapClassNamePostfix: ['5-1', '5-2', '1-1', '1-2', '1-3'] },
        '1-1-3': { maps: 5,  className: 'multi-map-3-1-1 multi-map-reverse', mapClassNamePostfix: ['2',   '3',   '1-1', '1-2', '1-3'] },
